// Sanitize and validate incoming lead data
const body = $input.item.json.body;

// Helper function to sanitize string inputs (prevent XSS)
function sanitize(str) {
  if (typeof str !== 'string') return str;
  return str
    .replace(/[<>"']/g, '') // Remove potentially dangerous characters
    .trim()
    .slice(0, 500); // Limit length
}

// Required fields
const required = ['email', 'name', 'company'];
const missing = required.filter(field => !body[field]);

if (missing.length > 0) {
  throw new Error(`Missing required fields: ${missing.join(', ')}`);
}

// Email validation
const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
if (!emailRegex.test(body.email)) {
  throw new Error('Invalid email format');
}

// Return validated and sanitized data
return {
  json: {
    email: body.email.toLowerCase().trim().slice(0, 255),
    name: sanitize(body.name),
    company: sanitize(body.company),
    phone: body.phone ? sanitize(body.phone) : null,
    notes: body.notes ? sanitize(body.notes) : '',
    source: body.source ? sanitize(body.source) : 'api',
    created_at: new Date().toISOString(),
    status: 'new'
  }
};

